question:
有以下程序代码
#include<iostream>
using namespace std;
class integer{
public:
integer(int value=0):value(value){}
integer operator+(integer itg){
return value+=itg.value;
}
friend ostream&operator<<(ostream&os,integer&it){
return os<<it.value;
}
private:
int value;
};
int main()
{
integer i;
integer ii;
ii=2+i;
cout<<"i="<<i<<",";
cout<<"ii="<<ii<<endl;
return 0;
}
编译情况或运行时输出是____

读下面C++程序：
#include<iostream.h>
class vehicle{
protected:
int wheels;
public:
vehicle(int in_wheels=4){wheels=in_wheels;}
int get_wheels(){return wheels;}
};
void main()
{
vehicle unicyclel;
vehicle unicycle2(3);
cout<<"Theunickele1has"<<unicyclel.get_wheels()<<"wheel.\n";
cout<<"Theunickele2has"<<unicycle2.get_wheels()<<"wheel.\n";
}
